192	    for (const gameCard of this.gameCards) {
193	      const location = gameCard.location;
194	      if (location.type !== "Table") {
195	        const key = location.type;
196	        if (!positionMap.has(key)) {
197	          positionMap.set(key, new Set());
198	        }
199	        const positions = positionMap.get(key)!;
200	        if (positions.has(location.position)) {
201	          throw new Error(`Duplicate position ${location.position} in ${location.type}`);
202	        }
203	        positions.add(location.position);
204	      }
205	    }
206	
207	    for (let i = 1; i < this.gameCards.length; i++) {
208	      const currentCard = this.gameCards[i].card.name;
209	      const previousCard = this.gameCards[i - 1].card.name;
210	      if (currentCard.localeCompare(previousCard) < 0) {
211	        throw new Error(`Cards are not sorted by display name: "${previousCard}" should come after "${currentCard}"`);
212	      }
213	    }
214	  }
