254	  /**
255	   * Fisher-Yates the library and apply the moves WITHOUT recording an event,
256	   * returning the moves performed. Used both by the public shuffle() (which
257	   * wraps it in a "shuffle library" event) and by mulligan() (which folds these
258	   * moves into its single atomic "mulligan" event).
259	   */
260	  private shuffleCollectingMoves(): CardMove[] {
261	    const libraryCards = this.gameCards.filter(isInLibrary);
262	
263	    // Create random number generator (seeded if randomSeed is provided)
264	    const random = this.randomSeed !== undefined ? new SeededRandom(this.randomSeed) : null;
265	    const getRandom = () => (random ? random.next() : Math.random());
266	
267	    // Fisher-Yates shuffle for the library cards array
268	    for (let i = libraryCards.length - 1; i > 0; i--) {
269	      const j = Math.floor(getRandom() * (i + 1));
270	      [libraryCards[i], libraryCards[j]] = [libraryCards[j], libraryCards[i]];
271	    }
272	
273	    const moves: CardMove[] = libraryCards.map((gameCard, index) => ({
274	      gameCardIndex: gameCard.gameCardIndex,
275	      fromLocation: gameCard.location,
276	      toLocation: { type: "Library", position: index },
277	    }));
278	
279	    moves.forEach((move) => this.executeMove(move, false));
280	
281	    this.validateInvariants();
282	
283	    return moves;
284	  }
