298	  /**
299	   * Deal the opening hand as a single atomic "deal opening hand" event carrying
300	   * its draw moves. Being one event (recorded after the draws) makes it the
301	   * most-recent live event while the player decides whether to keep — that's how
302	   * the hand-acceptance stage is derived (see isInHandAcceptanceStage).
303	   */
304	  private dealOpeningHand(browserTabId?: string): void {
305	    const moves = this.drawCardsCollectingMoves(OPENING_HAND_SIZE);
306	    this.eventLog.record({ eventName: "deal opening hand", moves, browserTabId });
307	  }
