309	  /**
310	   * Move up to `count` cards (fewer only for tiny test decks) from the top of
311	   * the library into the hand WITHOUT recording per-card events, returning the
312	   * moves. Callers fold these into a single atomic deal/mulligan event.
313	   */
314	  private drawCardsCollectingMoves(count: number): CardMove[] {
315	    const cardsToDraw = Math.min(count, this.listLibrary().length);
316	    const moves: CardMove[] = [];
317	    for (let i = 0; i < cardsToDraw; i++) {
318	      const topCard = this.listLibrary()[0];
319	      const move: CardMove = {
320	        gameCardIndex: topCard.gameCardIndex,
321	        fromLocation: topCard.location,
322	        toLocation: { type: "Hand", position: this.nextHandPosition() },
323	      };
324	      this.executeMove(move, false);
325	      moves.push(move);
326	    }
327	    return moves;
328	  }
