354	  /**
355	   * Mulligan: return the whole hand to the library, shuffle, and redraw a fresh
356	   * opening hand — recorded as a SINGLE atomic "mulligan" event carrying every
357	   * move it made. That keeps us in the hand-acceptance stage, bumps the derived
358	   * mulligan count, and (because it's one event) lets undo reverse the whole
359	   * mulligan in one step, restoring the previous hand and library exactly.
360	   */
361	  public mulligan(browserTabId?: string): WhatHappened {
362	    const moves: CardMove[] = [];
363	
364	    // Return every hand card to the bottom of the library, resetting any flipped
365	    // two-faced cards to their front face (library cards are shown face-down
366	    // anyway, and a freshly redrawn card should start on its front).
367	    this.listHand().forEach((gameCard) => {
368	      gameCard.currentFace = "front";
369	      const move: CardMove = {
370	        gameCardIndex: gameCard.gameCardIndex,
371	        fromLocation: gameCard.location,
372	        toLocation: { type: "Library", position: this.nextLibraryBottomPosition() },
373	      };
374	      this.executeMove(move, false);
375	      moves.push(move);
376	    });
377	
378	    moves.push(...this.shuffleCollectingMoves());
379	    moves.push(...this.drawCardsCollectingMoves(OPENING_HAND_SIZE));
380	
381	    this.eventLog.record({ eventName: "mulligan", moves, browserTabId });
382	
383	    this.validateInvariants();
384	    return { shuffling: true };
385	  }
