387	  /**
388	   * Grouch if the card isn't where it's supposed to be, then move it. Record the event.
389	   * @param move
390	   * @param recording - Shuffling or un-shuffling sets it to false, since that's recorded in its own way.
391	   * @param browserTabId - Optional browser tab identifier for event tracking
392	   */
393	  private executeMove(move: CardMove, recording: boolean = true, browserTabId?: string) {
394	    function verifyLocationsAreIdentical(expected: CardLocation, actual: CardLocation) {
395	      // hmm, this only matters for UNDO, or any sort of move replay. When I have that, move it
396	      const identical = expected.type == actual.type && (expected as any).position == (expected as any).position;
397	      if (!identical) {
398	        warn(
399	          `Warning! I'm supposed to move card ${move.gameCardIndex} (${gameCard.card.name}) from ${printLocation(
400	            move.toLocation
401	          )} but I found it in ${printLocation(gameCard.location)} `
402	        );
403	      }
404	    }
405	    const gameCard = this.gameCards[move.gameCardIndex];
406	    verifyLocationsAreIdentical(move.fromLocation, gameCard.location);
407	    gameCard.location = move.toLocation;
408	    if (recording) {
409	      this.eventLog.record({ eventName: "move card", move, browserTabId });
410	    }
411	  }
