573	  public moveHandCard(fromHandPosition: number, toHandPosition: number, browserTabId?: string): WhatHappened {
574	    function nameAndPosition(gameCard: GameCard) {
575	      return `${gameCard.card.name} (${(gameCard.location as HandLocation).position})`;
576	    }
577	    const span = trace.getActiveSpan();
578	    const handCards = this.listHand();
579	    span?.setAttributes({
580	      "game.hand_position.from": fromHandPosition,
581	      "game.hand_position.to": toHandPosition,
582	      "game.hand.begin": JSON.stringify(handCards.map(nameAndPosition), null, 2),
583	    });
584	
585	    if (fromHandPosition < 0 || fromHandPosition >= handCards.length) {
586	      throw new Error(`Invalid fromHandPosition: ${fromHandPosition}`);
587	    }
588	    if (toHandPosition < 0 || toHandPosition >= handCards.length) {
589	      throw new Error(`Invalid toHandPosition: ${toHandPosition}`);
590	    }
591	    if (fromHandPosition === toHandPosition) {
592	      throw new Error(`Cannot move card to same position: ${fromHandPosition}`);
593	    }
594	
595	    const cardToMove = handCards[fromHandPosition];
596	    let newPosition: number;
597	
598	    // Calculate new fractional position
599	    if (toHandPosition === 0) {
600	      // Moving to start
601	      newPosition = handCards[0].location.position - 1;
602	    } else if (toHandPosition === handCards.length - 1) {
603	      // Moving to end
604	      newPosition = handCards[handCards.length - 1].location.position + 1;
605	    } else {
606	      // Moving between cards
607	      // When moving right, insert after toHandPosition
608	      // When moving left, insert before toHandPosition
609	      if (fromHandPosition < toHandPosition) {
610	        // Moving right: insert after toHandPosition
611	        const leftCard = handCards[toHandPosition];
612	        const rightCard = handCards[toHandPosition + 1];
613	        if (rightCard) {
614	          newPosition = (leftCard.location.position + rightCard.location.position) / 2;
615	        } else {
616	          newPosition = leftCard.location.position + 1;
617	        }
618	      } else {
619	        // Moving left: insert before toHandPosition
620	        const rightCard = handCards[toHandPosition];
621	        const leftCard = handCards[toHandPosition - 1];
622	        newPosition = (leftCard.location.position + rightCard.location.position) / 2;
623	      }
624	    }
625	
626	    const move: CardMove = {
627	      gameCardIndex: cardToMove.gameCardIndex,
628	      fromLocation: cardToMove.location,
629	      toLocation: { type: "Hand", position: newPosition },
630	    };
631	    this.executeMove(move, true, browserTabId);
632	
633	    this.validateInvariants();
634	
635	    // Determine which cards shifted for animation
636	    const movedLeft: GameCard[] = [];
637	    const movedRight: GameCard[] = [];
638	
639	    // Cards that shifted depend on direction of move
640	    if (fromHandPosition < toHandPosition) {
641	      // Moved right: cards between old and new position moved left
642	      for (let i = fromHandPosition + 1; i <= toHandPosition; i++) {
643	        movedLeft.push(handCards[i]);
644	      }
645	    } else {
646	      // Moved left: cards between new and old position moved right
647	      for (let i = toHandPosition; i < fromHandPosition; i++) {
648	        movedRight.push(handCards[i]);
649	      }
650	    }
651	
652	    const whatHappened = {
653	      movedLeft: movedLeft.length > 0 ? movedLeft : undefined,
654	      movedRight: movedRight.length > 0 ? movedRight : undefined,
655	      dropppedFromLeft: fromHandPosition > toHandPosition ? cardToMove : undefined,
656	      dropppedFromRight: fromHandPosition < toHandPosition ? cardToMove : undefined,
657	    };
658	    span?.setAttributes({
659	      "game.whatHappened": JSON.stringify(whatHappened, null, 2),
660	      "game.hand.end": JSON.stringify(this.listHand().map(nameAndPosition), null, 2),
661	    });
662	    return whatHappened;
663	  }
