665	  public flipCard(gameCardIndex: number, browserTabId?: string): WhatHappened {
666	    const gameCard = this.gameCards[gameCardIndex];
667	    if (!gameCard) {
668	      throw new Error(`Game card with index ${gameCardIndex} not found`);
669	    }
670	
671	    if (!gameCard.card.twoFaced) {
672	      throw new Error(`Card ${gameCard.card.name} is not a two-faced card`);
673	    }
674	
675	    const newFace = gameCard.currentFace === "front" ? "back" : "front";
676	    if (gameCard.currentFace === newFace) {
677	      warn(`Card ${gameCard.card.name} is already on face ${newFace}`);
678	    }
679	
680	    // Update the current face without recording an event
681	    gameCard.currentFace = newFace;
682	    return {};
683	  }
