692	  public findPrevCardInZone(currentCardIndex: number): number | null {
693	    const currentCard = this.findCardByIndex(currentCardIndex);
694	    if (!currentCard) {
695	      return null;
696	    }
697	
698	    const location = currentCard.location;
699	
700	    // Table cards don't have position ordering
701	    if (location.type === "Table") {
702	      return null;
703	    }
704	
705	    // Get the ordered list of cards in the same zone
706	    let cardsInZone: readonly GameCard[];
707	    if (location.type === "Library") {
708	      cardsInZone = this.listLibrary();
709	    } else if (location.type === "Hand") {
710	      cardsInZone = this.listHand();
711	    } else if (location.type === "Revealed") {
712	      cardsInZone = this.listRevealed();
713	    } else if (location.type === "CommandZone") {
714	      cardsInZone = this.listCommandZone();
715	    } else {
716	      return null;
717	    }
718	
719	    // Find the current card's position in the ordered list
720	    const currentPosition = cardsInZone.findIndex(gc => gc.gameCardIndex === currentCardIndex);
721	    if (currentPosition === -1 || currentPosition === 0) {
722	      return null; // Card not found or is first card
723	    }
724	
725	    // Return the previous card's index
726	    return cardsInZone[currentPosition - 1].gameCardIndex;
727	  }
