729	  public findNextCardInZone(currentCardIndex: number): number | null {
730	    const currentCard = this.findCardByIndex(currentCardIndex);
731	    if (!currentCard) {
732	      return null;
733	    }
734	
735	    const location = currentCard.location;
736	
737	    // Table cards don't have position ordering
738	    if (location.type === "Table") {
739	      return null;
740	    }
741	
742	    // Get the ordered list of cards in the same zone
743	    let cardsInZone: readonly GameCard[];
744	    if (location.type === "Library") {
745	      cardsInZone = this.listLibrary();
746	    } else if (location.type === "Hand") {
747	      cardsInZone = this.listHand();
748	    } else if (location.type === "Revealed") {
749	      cardsInZone = this.listRevealed();
750	    } else if (location.type === "CommandZone") {
751	      cardsInZone = this.listCommandZone();
752	    } else {
753	      return null;
754	    }
755	
756	    // Find the current card's position in the ordered list
757	    const currentPosition = cardsInZone.findIndex(gc => gc.gameCardIndex === currentCardIndex);
758	    if (currentPosition === -1 || currentPosition === cardsInZone.length - 1) {
759	      return null; // Card not found or is last card
760	    }
761	
762	    // Return the next card's index
763	    return cardsInZone[currentPosition + 1].gameCardIndex;
764	  }
