766	  public undo(gameEventIndex: number, browserTabId?: string): GameState {
767	    const event = this.eventLog.getEvents()[gameEventIndex];
768	
769	    // A mulligan is atomic: reverse every move it made, in reverse order, to
770	    // restore the previous hand and library exactly.
771	    if (event.eventName === "mulligan") {
772	      for (let i = event.moves.length - 1; i >= 0; i--) {
773	        const move = event.moves[i];
774	        this.executeMove({ gameCardIndex: move.gameCardIndex, fromLocation: move.toLocation, toLocation: move.fromLocation }, false);
