33	
34	export type MoveCardEvent = {
35	  eventName: "move card";
36	  move: CardMove;
37	};
38	
39	
40	export type UndoEvent = {
41	  eventName: "undo";
42	  originalEventIndex: number;
43	};
44	
45	/**
46	 * An opening hand being dealt, as a single atomic event. `moves` is the draws
47	 * it performed (Library→Hand), so the deal is one line in history rather than
48	 * seven. It is the most-recent "live" event while the player decides whether to
49	 * keep their hand — that position is how the hand-acceptance (mulligan) stage is
50	 * derived from the log (see GameEventLog.isInHandAcceptanceStage()). Not
51	 * undoable (like "start game") — there's nothing to go back to.
52	 */
53	export type DealOpeningHandEvent = {
54	  eventName: "deal opening hand";
55	  moves: CardMove[];
56	};
57	
58	/**
59	 * A mulligan as a single atomic event: `moves` is everything it did, in order —
60	 * return the hand to the library, shuffle, redraw. Undoing this event reverses
61	 * all those moves at once, restoring the previous hand and library exactly. The
62	 * mulligan count is the number of live (not-undone) mulligan events.
63	 */
64	export type MulliganEvent = {
65	  eventName: "mulligan";
66	  moves: CardMove[];
67	};
68	
69	/**
70	 * Convert compact shuffle moves to full CardMove array
71	 */
72	export function expandCompactShuffleMoves(compactMoves: [number, number, number][]): CardMove[] {
73	  return compactMoves.map(([gameCardIndex, fromPosition, toPosition]) => ({
74	    gameCardIndex,
75	    fromLocation: { type: "Library" as const, position: fromPosition },
76	    toLocation: { type: "Library" as const, position: toPosition },
77	  }));
78	}
79	
80	/**
81	 * Convert full CardMove array to compact shuffle moves (only for Library-to-Library moves)
82	 * Even if a card by luck didn't move, store that.
83	 * Otherwise it looks like we shuffled only some of the library.
84	 */
85	export function compactShuffleMoves(moves: CardMove[]): [number, number, number][] {
86	  return moves.map((move) => [
87	    move.gameCardIndex,
88	    (move.fromLocation as { type: "Library"; position: number }).position,
89	    (move.toLocation as { type: "Library"; position: number }).position,
90	  ]);
91	}
92	
93	export function nameMove(move: CardMove): string {
94	  // from library to hand is "Draw"
95	  // from anywhere to revealed is "Reveal"
96	  // from anywhere to Table is "Play"
97	  // from anywhere to Library(0) is "Put on Top"
98	  // from anywhere to Library(nonzero) is "Put in library(position)"
99	  // from one position to another in the same location is "Move around"
100	  if (move.fromLocation.type === "Library" && move.toLocation.type === "Hand") {
101	    return "Draw";
102	  }
103	  if (move.toLocation.type === "Revealed") {
104	    return "Reveal";
105	  }
106	  if (move.toLocation.type === "Table") {
107	    return "Play";
108	  }
109	  if (move.toLocation.type === "Library" && move.toLocation.position === 0) {
110	    return "Put on top";
111	  }
112	  if (move.toLocation.type === "Library") {
113	    return `Put in library(${move.toLocation.position})`;
114	  }
115	  if (move.fromLocation.type === move.toLocation.type) {
116	    return `Move around in ${move.toLocation.type}`;
117	  }
118	  return `Move from ${move.fromLocation.type} to ${move.toLocation.type}`;
119	}
