121	export type GameEventDefinition = (ShuffleEvent | StartEvent | MoveCardEvent | UndoEvent | DealOpeningHandEvent | MulliganEvent) & EventProvenance;
122	
123	export type GameEvent = GameEventDefinition & GameEventIdentifier;
124	
125	export class GameEventLog {
126	  private readonly events: GameEvent[] = [];
127	
128	  static newLog() {
129	    return new GameEventLog([]);
130	  }
131	
132	  static fromPersisted(events: GameEvent[]) {
133	    return new GameEventLog(events);
134	  }
135	
136	  private constructor(events: GameEvent[]) {
137	    this.events = events;
138	  }
139	
140	  public record(event: GameEventDefinition): GameEvent {
141	    // this should be an atomic operation.
142	    // However, I don't think it's currently possible for this object to be shared among threads, since each request is synchronous,
143	    // and the server hydrates a new object for each request.
144	    const gameEvent: GameEvent = {
145	      ...event,
146	      gameEventIndex: this.events.length,
147	    };
148	    this.events.push(gameEvent);
149	    return gameEvent;
150	  }
151	
152	  public getEvents() {
153	    return [...this.events];
154	  }
155	
156	  public recordUndo(event: GameEvent, browserTabId?: string): GameEvent {
157	    if (event.eventName === "undo") {
158	      throw new Error("Cannot undo an undo, use redo instead");
159	    }
160	    if (event.eventName === "start game") {
161	      throw new Error("Cannot undo start game");
162	    }
163	    if (event.eventName === "deal opening hand") {
164	      throw new Error("Cannot undo deal opening hand");
165	    }
166	    // A "mulligan" event IS undoable — see GameState.undo, which reverses its moves.
167	
168	    const undoEvent: UndoEvent & EventProvenance = {
169	      eventName: "undo",
170	      originalEventIndex: event.gameEventIndex,
171	      browserTabId,
172	    };
173	    return this.record(undoEvent);
174	  }
175	
176	  public reverse(event: GameEventDefinition): MoveCardEvent | ShuffleEvent {
177	    switch (event.eventName) {
178	      case "undo":
179	        return this.events[event.originalEventIndex] as MoveCardEvent | ShuffleEvent;
180	      case "move card":
181	        return {
182	          eventName: "move card",
183	          move: {
184	            gameCardIndex: event.move.gameCardIndex,
185	            fromLocation: event.move.toLocation,
186	            toLocation: event.move.fromLocation,
187	          },
188	        };
189	      case "shuffle library":
190	        // Use compact moves if available, otherwise fall back to full moves
191	        const movesToReverse = expandCompactShuffleMoves(event.compactMoves);
192	
193	        return {
194	          eventName: "shuffle library",
195	          compactMoves: compactShuffleMoves(
196	            movesToReverse.map((move) => ({
197	              gameCardIndex: move.gameCardIndex,
198	              fromLocation: move.toLocation,
199	              toLocation: move.fromLocation,
200	            }))
201	          ),
202	        };
203	      case "start game":
204	        throw new Error("there isn't an event for reversing start game");
205	      case "deal opening hand":
206	      case "mulligan":
207	        throw new Error(`there isn't an event for reversing ${event.eventName}`);
208	    }
209	  }
210	
211	  /**
212	   * Is this event eligible for undo?
213	   *
214	   * It is eligible for undo if:
215	   * - it is not an undo event
216	   * - it is not Start Game
217	   * - Either:
218	   *   - it is the most recent event
219	   *   - The events after are paired: each non-undo has a later undo of it.
220	   *
221	   * @param gameEventIndex
222	   * @returns boolean
223	   */
224	  public canBeUndone(gameEventIndex: number): boolean {
225	    const event = this.events[gameEventIndex];
226	    if (!event) return false;
227	
228	    // Cannot undo these event types ("mulligan" IS undoable)
229	    if (event.eventName === "undo" || event.eventName === "start game" || event.eventName === "deal opening hand") {
230	      return false;
231	    }
232	
233	    // Cannot undo if already undone
234	    if (this.hasBeenUndone(gameEventIndex)) {
235	      return false;
236	    }
237	
238	    // If it's the most recent event, it can be undone
239	    const mostRecentIndex = this.events.length - 1;
240	    if (gameEventIndex === mostRecentIndex) {
241	      return true;
242	    }
243	
244	    const moreRecentEvents = this.events.slice(gameEventIndex + 1);
245	    const aMoreRecentUndoableEvent = moreRecentEvents.find((event) => event.eventName !== "undo" && !this.hasBeenUndone(event.gameEventIndex));
246	    return !aMoreRecentUndoableEvent;
247	  }
248	
249	  /**
250	   * Should this one be crossed out, and ineligible for undo?
251	   * @param gameEventIndex
252	   * @returns True if there's a later event that is an undo of this one.
253	   */
254	  public hasBeenUndone(gameEventIndex: number): boolean {
255	    return this.events.slice(gameEventIndex + 1).some((event) => event.eventName === "undo" && event.originalEventIndex === gameEventIndex);
256	  }
257	
258	  /**
259	   * Are we still in the opening-hand acceptance (mulligan) stage? Derived purely
260	   * from the event log so that undo restores it automatically.
261	   *
262	   * Walk back through the "live" events (skipping undo events and events that
263	   * have been undone). Hand rearrangement (a Hand→Hand move) is transparent — it
264	   * doesn't end the stage — so we look past it. The first live, non-rearrange
265	   * event we hit decides: if it's the dealing of a hand (initial deal or a
266	   * mulligan), we're still accepting; anything else (a draw, play, reveal,
267	   * manual shuffle, ...) means play has begun.
268	   */
269	  public isInHandAcceptanceStage(): boolean {
270	    for (let i = this.events.length - 1; i >= 0; i--) {
271	      const event = this.events[i];
272	      if (event.eventName === "undo" || this.hasBeenUndone(i)) {
273	        continue;
274	      }
275	      if (event.eventName === "move card" && event.move.fromLocation.type === "Hand" && event.move.toLocation.type === "Hand") {
276	        continue; // rearranging the hand is transparent
277	      }
278	      return event.eventName === "deal opening hand" || event.eventName === "mulligan";
279	    }
280	    return false;
281	  }
282	
283	  /** How many mulligans have been taken (number of live "mulligan" events). */
284	  public mulliganCount(): number {
285	    return this.events.filter((event, i) => event.eventName === "mulligan" && !this.hasBeenUndone(i)).length;
286	  }
287	}
