import { Server } from "node:http";
import { AddressInfo } from "node:net";
import { createApp } from "../src/app.js";
import { GameState, TableInfo } from "../src/GameState.js";
import { InMemoryCardRepositoryAdapter } from "../src/port-card-repository/InMemoryCardRepositoryAdapter.js";
import { InMemoryPersistStateAdapter } from "../src/port-persist-state/InMemoryPersistStateAdapter.js";
import { InMemoryPersistPrepAdapter } from "../src/port-persist-prep/InMemoryPersistPrepAdapter.js";
import { FakeTabletopGateway } from "../src/port-tabletop/FakeTabletopGateway.js";
import { RetrieveDeckPort } from "../src/port-deck-retrieval/types.js";
import { CardDefinition, Deck, PERSISTED_DECK_VERSION } from "../src/types.js";
import { lightningBolt, testProvenance } from "./generators.js";

/**
 * Send-then-commit (JES-127, B3/B4): at a table, /play-card and /discard-card
 * send the card to the Tabletop FIRST; only on success does the game state
 * change. On failure the card stays in hand — a play that silently missed the
 * table is worse than one that says it failed. Solo games never touch the
 * tabletop port.
 *
 * Real HTTP against the real app with fakes behind it (no mocks).
 */

const forest: CardDefinition = {
  name: "Forest",
  scryfallId: "def456",
  multiverseid: 54321,
  twoFaced: false,
  oracleCardName: "Forest",
  colorIdentity: ["G"],
  set: "LEA",
  cardTypes: ["Land"],
};

const testDeck: Deck = {
  version: PERSISTED_DECK_VERSION,
  id: 77,
  name: "Test Deck",
  totalCards: 2,
  commanders: [],
  cards: [lightningBolt, forest],
  provenance: testProvenance,
};

const noDecks: RetrieveDeckPort = {
  listAvailableDecks: () => {
    throw new Error("not used in this test");
  },
  canHandle: () => false,
  retrieveDeck: async () => {
    throw new Error("not used in this test");
  },
};

describe("send-then-commit to the table", () => {
  let server: Server;
  let baseUrl: string;
  let fakeTabletop: FakeTabletopGateway;
  let persistState: InMemoryPersistStateAdapter;
  let cardRepo: InMemoryCardRepositoryAdapter;

  beforeAll(async () => {
    cardRepo = new InMemoryCardRepositoryAdapter();
    await cardRepo.saveCards([lightningBolt, forest]);
    persistState = new InMemoryPersistStateAdapter(cardRepo);
    const persistPrep = new InMemoryPersistPrepAdapter(cardRepo);
    fakeTabletop = new FakeTabletopGateway();

    const app = createApp(noDecks, persistState, persistPrep, cardRepo, fakeTabletop);
    server = await new Promise<Server>((resolve) => {
      const s = app.listen(0, () => resolve(s));
    });
    baseUrl = `http://localhost:${(server.address() as AddressInfo).port}`;
  });

  afterAll(async () => {
    await new Promise<void>((resolve) => server.close(() => resolve()));
  });

  beforeEach(() => {
    fakeTabletop.succeedAgain();
    fakeTabletop.sentEvents.length = 0;
  });

  /** Make a game with every card in hand, save it, return it. */
  async function gameInProgress(gameId: number, tableInfo?: TableInfo): Promise<GameState> {
    const game = GameState.newGame(gameId, 1, 1, testDeck, undefined, tableInfo);
    for (const gc of game.getCards()) {
      game.putInHandByGameCardIndex(gc.gameCardIndex);
    }
    await persistState.save(game.toPersistedGameState());
    return game;
  }

  async function playCard(gameId: number, gameCardIndex: number) {
    return fetch(`${baseUrl}/play-card/${gameId}/${gameCardIndex}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({}),
    });
  }

  function cardIndexOf(game: GameState, name: string): number {
    return game.getCards().find((gc) => gc.card.name === name)!.gameCardIndex;
  }

  const tableInfo: TableInfo = { tableName: "Friday Night", playerName: "Jess", seatId: "abc12345" };

  test("at a table, a nonland play sends zoneHint 'stack' to the table, then commits", async () => {
    const game = await gameInProgress(101, tableInfo);
    const boltIndex = cardIndexOf(game, "Lightning Bolt");

    const response = await playCard(101, boltIndex);
    expect(response.status).toBe(200);

    expect(fakeTabletop.sentEvents).toHaveLength(1);
    const { tableName, event } = fakeTabletop.sentEvents[0];
    expect(tableName).toBe("Friday Night");
    expect(event.zoneHint).toBe("stack");
    expect(event.initiator).toEqual({ seatId: "abc12345", playerName: "Jess" });
    expect(event.card.scryfallId).toBe(lightningBolt.scryfallId);
    expect(event.card.instanceId).toBe(game.getCards()[boltIndex].cardInstanceId);

    const persisted = await persistState.retrieve(101);
    expect(persisted!.gameCards[boltIndex].location.type).toBe("Table");
  });

  test("a land play sends zoneHint 'battlefield'", async () => {
    const game = await gameInProgress(102, tableInfo);
    const forestIndex = cardIndexOf(game, "Forest");

    const response = await playCard(102, forestIndex);
    expect(response.status).toBe(200);
    expect(fakeTabletop.sentEvents[0].event.zoneHint).toBe("battlefield");
  });

  test("when the table is unreachable, the play is BLOCKED: error response, card stays in hand", async () => {
    const game = await gameInProgress(103, tableInfo);
    const boltIndex = cardIndexOf(game, "Lightning Bolt");
    fakeTabletop.failWith(new Error("connection refused"));

    const response = await playCard(103, boltIndex);
    expect(response.status).toBe(502);
    const body = await response.text();
    expect(body).toContain("Friday Night");

    const persisted = await persistState.retrieve(103);
    expect(persisted!.gameCards[boltIndex].location.type).toBe("Hand");
    // and no play event was recorded
    expect(persisted!.events.filter((e) => e.eventName === "move card")).toHaveLength(0);
  });

  test("a solo game never touches the tabletop port", async () => {
    const game = await gameInProgress(104); // no tableInfo
    const boltIndex = cardIndexOf(game, "Lightning Bolt");

    const response = await playCard(104, boltIndex);
    expect(response.status).toBe(200);
    expect(fakeTabletop.sentEvents).toHaveLength(0);

    const persisted = await persistState.retrieve(104);
    expect(persisted!.gameCards[boltIndex].location.type).toBe("Table");
  });
});

