      ? `htmx.ajax('GET', '/close-card-modal', {target: '#card-modal-container', swap: 'innerHTML'}); if (event.detail.successful) htmx.ajax('GET', '/close-modal', {target: '#modal-container', swap: 'innerHTML'})`
